function renderDocuments(){const list=$('#documentList');list.innerHTML=documents.map((d,i)=>`<button class="doc-card ${i===0?'active':''}" data-doc="${i}"><span class="doc-thumb">${d.short}</span><span><b class="doc-tag">${d.tag}</b><strong>${d.title}</strong><small>${d.meta}</small>${d.spanishFile?'<em class="official-es">ESPAÑOL OFICIAL DISPONIBLE</em>':''}</span></button>`).join('');$$('[data-doc]').forEach(b=>b.onclick=()=>{currentDocLanguage='en';selectDocument(+b.dataset.doc)});selectDocument(0)}
