function renderQuestion(){const q=questions[current];$('#questionLabel').textContent=`PREGUNTA ${current+1} DE ${questions.length}`;$('#quizProgress').style.width=`${(current+1)*10}%`;$('#questionText').textContent=q.q;$('#questionTranslation').textContent=q.es;$('#questionTranslation').hidden=true;$('#translateToggle').textContent='Ver apoyo en español';$('#feedback').hidden=true;$('#answerList').innerHTML=q.a.map((a,i)=>`<button class="answer ${state.answers[current]==i?'selected':''} ${state.checked[current]?(i===q.correct?'correct':state.answers[current]===i?'wrong':''):''}" data-answer="${i}"><span>${'ABC'[i]}</span>${a}</button>`).join('');$$('[data-answer]').forEach(b=>b.onclick=()=>{if(state.checked[current])return;state.answers[current]=+b.dataset.answer;save();renderQuestion()});renderMap()}
function renderMap(){$('#questionMap').innerHTML=questions.map((_,i)=>`<button data-q="${i}" class="${i===current?'active':''} ${state.answers[i]!=null?'answered':''}">${i+1}</button>`).join('');$$('[data-q]').forEach(b=>b.onclick=()=>{current=+b.dataset.q;renderQuestion()})}
function checkAnswer(){if(state.answers[current]==null){$('#feedback').hidden=false;$('#feedback').textContent='Selecciona una respuesta antes de comprobar.';return}state.checked[current]=true;save();renderQuestion();const q=questions[current],ok=state.answers[current]===q.correct;$('#feedback').hidden=false;$('#feedback').innerHTML=`<strong>${ok?'Correcto.':'Respuesta incorrecta.'}</strong> ${q.why}`}
function updateStats(){
 const quizAnswered=Object.keys(state.answers).length,quizChecked=Object.keys(state.checked).length,quizCorrect=Object.keys(state.checked).filter(i=>state.answers[i]===questions[i].correct).length;
 const topics={general:{answered:0,correct:0},brakes:{answered:0,correct:0},passenger:{answered:0,correct:0}};let sourceAnswered=0,sourceChecked=0,sourceCorrect=0;
 if(typeof pageForms!=='undefined'&&typeof sourceAnswers!=='undefined')Object.entries(pageForms).forEach(([page,form])=>{const answers=sourceAnswers[`p${page}`]||{},topic=form.section.includes('Air Brake')?'brakes':form.section.includes('Passenger')?'passenger':'general';Object.entries(answers).forEach(([n,letter])=>{sourceAnswered++;if(form.key?.[n]){sourceChecked++;topics[topic].answered++;if(form.key[n]===letter){sourceCorrect++;topics[topic].correct++}}})});
 const answered=quizAnswered+sourceAnswered,checked=quizChecked+sourceChecked,correct=quizCorrect+sourceCorrect,accuracy=checked?Math.round(correct/checked*100):0;topics.general.answered+=quizChecked;topics.general.correct+=quizCorrect;
 $('#answeredStat').textContent=answered;$('#accuracyStat').textContent=checked?`${accuracy}%`:'—';
 [['general','#generalBar','#generalFill'],['brakes','#brakesBar','#brakesFill'],['passenger','#passengerBar','#passengerFill']].forEach(([topic,label,fill])=>{const t=topics[topic],value=t.answered?Math.round(t.correct/t.answered*100):0;$(label).textContent=`${value}%`;$(fill).style.width=`${value}%`});
 const completion=Math.min(100,Math.round(sourceAnswered/255*100));$('#heroPercent').textContent=`${completion}%`;$('.ring').style.background=`conic-gradient(var(--amber) 0 ${completion}%,#dfe5e7 ${completion}%)`;$('#heroAnswered').textContent=`${sourceAnswered}/255`;$('#heroProgressCopy').textContent=`${sourceAnswered} de 255 espacios respondidos.`;$('#heroProgressTitle').textContent=sourceAnswered===255?'Cuestionario completado':sourceAnswered?'Sigue donde lo dejaste':'Comienza cuando quieras';
 const studyDays=JSON.parse(localStorage.getItem('rutaCdlStudyDays')||'[]').sort(),daySet=new Set(studyDays);let streak=0,cursor=new Date();if(!daySet.has(cursor.toISOString().slice(0,10)))cursor.setDate(cursor.getDate()-1);while(daySet.has(cursor.toISOString().slice(0,10))){streak++;cursor.setDate(cursor.getDate()-1)}$('#streakStat').textContent=streak;
 if(quizChecked===questions.length)localStorage.setItem('rutaCdlBest',Math.max(quizCorrect,+localStorage.getItem('rutaCdlBest')||0));const history=JSON.parse(localStorage.getItem('rutaCdlExamHistory')||'[]'),bestExam=history.reduce((m,x)=>Math.max(m,x.percent||0),0),best=+localStorage.getItem('rutaCdlBest')||0;$('#bestScore').textContent=bestExam?`${bestExam}%`:best?`${best}/10`:'—';
 $('#examHistory').innerHTML=history.length?history.slice(0,6).map(attempt=>`<article class="history-attempt"><strong>${attempt.percent}%</strong><span>${attempt.score}/${attempt.size} correctas</span><small>${new Date(attempt.date).toLocaleDateString('es-US')}</small></article>`).join(''):'<p>Completa un examen personalizado para iniciar tu historial.</p>';
}
function showPractice(mode){$$('[data-practice]').forEach(b=>b.classList.toggle('active',b.dataset.practice===mode));$('#quizShell').hidden=mode!=='quiz';$('#matchShell').hidden=mode!=='match';$('#rapidShell').hidden=mode!=='rapid';$('#sourceExamShell').hidden=mode!=='source';$('#customExamShell').hidden=mode!=='custom';if(mode==='match')renderMatch();if(mode==='rapid')renderRapid();if(mode==='source')renderSourceExam();if(mode==='custom')renderExamBuilder()}
const pairs=[['Service brake','Freno de servicio'],['Parking brake','Freno de estacionamiento'],['Emergency brake','Freno de emergencia'],['Air pressure','Presión de aire'],['Slack adjuster','Ajustador de holgura'],['Brake chamber','Cámara de freno'],['Air compressor','Compresor de aire'],['Governor','Gobernador'],['Supply pressure gauge','Medidor de presión de suministro'],['Low air warning','Advertencia de baja presión'],['Spring brakes','Frenos de resorte'],['Brake fade','Desvanecimiento de frenos'],['Reflective triangles','Triángulos reflectantes'],['Stopping distance','Distancia de parada'],['Blind spot','Punto ciego'],['Standee line','Línea para pasajeros de pie'],['Emergency exit','Salida de emergencia'],['Railroad crossing','Cruce ferroviario']];let matchPick=null,matched=[];
function renderMatch(){const left=pairs.map((p,i)=>({text:p[0],id:i,side:'a'}));const right=[...pairs].reverse().map((p,ri)=>({text:p[1],id:pairs.length-1-ri,side:'b'}));$('#matchShell').innerHTML=`<div class="section-heading compact"><div><p class="eyebrow dark"><span></span> Relacionar</p><h2>Une cada concepto</h2><p>Selecciona un término en inglés y su equivalente en español.</p></div><strong>${matched.length}/${pairs.length}</strong></div><div class="match-grid">${[left,right].map(col=>`<div>${col.map(x=>`<button class="match-card ${matched.includes(x.id)?'matched':''}" data-pair="${x.id}" data-side="${x.side}">${x.text}</button>`).join('')}</div>`).join('')}</div>`;$$('[data-pair]').forEach(b=>b.onclick=()=>pickMatch(b))}
function pickMatch(b){if(matched.includes(+b.dataset.pair))return;if(!matchPick){matchPick=b;b.classList.add('selected');return}if(matchPick.dataset.side!==b.dataset.side&&matchPick.dataset.pair===b.dataset.pair){matched.push(+b.dataset.pair);matchPick=null;renderMatch()}else{matchPick.classList.remove('selected');matchPick=b;b.classList.add('selected')}}
let rapidTimer=null,rapidSeconds=60,rapidCorrect=0,rapidAnswered=0,rapidQuestion=0;
function renderRapid(){clearInterval(rapidTimer);$('#rapidShell').innerHTML=`<div class="rapid-card"><p class="eyebrow dark"><span></span> Reto relámpago</p><div class="timer">60</div><h2>¿Cuántas puedes responder en un minuto?</h2><p>Retroalimentación inmediata, orden aleatorio y resultado final.</p><button class="primary" id="startRapid">Empezar reto →</button></div>`;$('#startRapid').onclick=startRapid}
function startRapid(){rapidSeconds=60;rapidCorrect=0;rapidAnswered=0;rapidQuestion=Math.floor(Math.random()*questions.length);renderRapidQuestion();rapidTimer=setInterval(()=>{rapidSeconds--;const timer=$('#rapidTime');if(timer)timer.textContent=rapidSeconds;if(rapidSeconds<=0)finishRapid()},1000)}
function renderRapidQuestion(){const q=questions[rapidQuestion];$('#rapidShell').innerHTML=`<div class="rapid-live"><div class="rapid-live-head"><strong id="rapidTime">${rapidSeconds}</strong><span>${rapidCorrect} correctas · ${rapidAnswered} respondidas</span></div><small>RETO RELÁMPAGO</small><h3>${q.q}</h3><div class="scenario-options">${q.a.map((x,i)=>`<button data-rapid-answer="${i}">${x}</button>`).join('')}</div></div>`;$$('[data-rapid-answer]').forEach(b=>b.onclick=()=>{rapidAnswered++;if(+b.dataset.rapidAnswer===q.correct)rapidCorrect++;rapidQuestion=(rapidQuestion+1+Math.floor(Math.random()*(questions.length-1)))%questions.length;renderRapidQuestion()})}
function finishRapid(){clearInterval(rapidTimer);rapidTimer=null;$('#rapidShell').innerHTML=`<div class="rapid-card"><p class="eyebrow dark"><span></span> RETO COMPLETADO</p><div class="timer">${rapidCorrect}</div><h2>respuestas correctas</h2><p>${rapidAnswered} respondidas · ${rapidAnswered?Math.round(rapidCorrect/rapidAnswered*100):0}% de precisión</p><button class="primary" id="startRapid">Intentar de nuevo →</button></div>`;$('#startRapid').onclick=startRapid}
const cardDeck=[['Service brake','Freno de servicio','Applies and releases the brakes during normal driving.'],['Parking brake','Freno de estacionamiento','Holds the vehicle when parked.'],['Emergency brake','Freno de emergencia','Uses parts of the service and parking systems during a failure.'],['Brake chamber','Cámara de freno','Converts air pressure into mechanical force.'],['Slack adjuster','Ajustador de holgura','Connects the brake chamber pushrod to the brake mechanism.'],['Air compressor','Compresor de aire','Pumps air into the storage tanks.'],['Governor cut-out','Corte del gobernador','The point where the compressor stops pumping air.'],['Low air warning','Advertencia de baja presión','Must activate before pressure falls below the specified limit.'],['Standee line','Línea para pasajeros de pie','Riders must remain behind it while the bus is moving.'],['Reflective triangles','Triángulos reflectantes','Warning devices placed when a commercial vehicle is stopped.'],['GVWR','Clasificación de peso bruto vehicular','Manufacturer-specified loaded weight rating for a single vehicle.'],['Controlled braking','Frenado controlado','Braking hard without locking the wheels.']];let cardIndex=0,cardRevealed=false;const cardMastery=JSON.parse(localStorage.getItem('rutaCdlCardMastery')||'{}');
function renderCardDeck(){const c=cardDeck[cardIndex],known=Object.values(cardMastery).filter(Boolean).length;$('#academyStage').innerHTML=`<div class="activity-panel card-deck-panel"><div class="deck-progress"><span>TARJETA ${cardIndex+1} / ${cardDeck.length}</span><strong>${known} dominadas</strong></div><button class="study-flashcard ${cardRevealed?'revealed':''}" id="studyFlashcard"><div class="card-front"><small>INGLÉS</small><h3>${c[0]}</h3><span>Toca para revelar</span></div><div class="card-back"><small>ESPAÑOL + FUNCIÓN</small><h3>${c[1]}</h3><p>${c[2]}</p></div></button><div class="card-controls"><button id="cardAgain">↺ Necesito repasarla</button><button id="cardKnow">✓ La recuerdo</button></div></div>`;$('#studyFlashcard').onclick=()=>{cardRevealed=!cardRevealed;renderCardDeck()};$('#cardAgain').onclick=()=>{cardMastery[cardIndex]=false;localStorage.setItem('rutaCdlCardMastery',JSON.stringify(cardMastery));cardIndex=(cardIndex+1)%cardDeck.length;cardRevealed=false;renderCardDeck()};$('#cardKnow').onclick=()=>{cardMastery[cardIndex]=true;localStorage.setItem('rutaCdlCardMastery',JSON.stringify(cardMastery));cardIndex=(cardIndex+1)%cardDeck.length;cardRevealed=false;renderCardDeck()}}
cardDeck.push(['Supply pressure gauge','Medidor de presión de suministro','Shows pressure in the air tanks.'],['Application pressure gauge','Medidor de presión de aplicación','Shows air pressure applied to the brakes.'],['Spring brakes','Frenos de resorte','Apply mechanically when air pressure is lost.'],['Brake fade','Desvanecimiento de frenos','Loss of braking power caused by excessive heat.'],['Stopping distance','Distancia de parada','Perception, reaction, brake lag and braking distance combined.'],['Escape ramp','Rampa de escape','A designated path for vehicles that cannot stop on a downgrade.'],['Blind spot','Punto ciego','An area around the vehicle that mirrors do not show.'],['Offtracking','Desviación de trayectoria','Rear wheels follow a different path in a turn.'],['Emergency exit','Salida de emergencia','Must be marked, operational and securely closed.'],['Railroad crossing','Cruce ferroviario','Requires special observation and stopping procedures for buses.'],['Hazardous materials','Materiales peligrosos','Cargo regulated because it may pose unreasonable risk.'],['Pre-trip inspection','Inspección previa al viaje','Systematic verification that the vehicle is safe to operate.']);
