function shuffle(items){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function renderExamBuilder(){customExam=[];customExamAnswers={};customExamFinished=false;$('#customExamShell').innerHTML=`<div class="exam-builder"><p class="eyebrow dark"><span></span> CONSTRUCTOR DE EXAMEN</p><h2>Elige la duración de tu simulación</h2><p>Las preguntas se seleccionan de las <strong>${verifiedQuestionBank.length} respuestas verificadas</strong> de las 26 páginas. Verás siempre la página original para responder sin alterar su contenido.</p><div class="exam-size-grid">${[10,25,50,verifiedQuestionBank.length].map(n=>`<button data-exam-size="${n}"><strong>${n}</strong><span>${n===verifiedQuestionBank.length?'Examen integral':'preguntas aleatorias'}</span></button>`).join('')}</div><label class="exam-filter">Sección <select id="examSection"><option value="all">Todas las secciones</option><option value="General">Conocimiento general</option><option value="Air Brake">Frenos de aire</option><option value="Passenger">Pasajeros</option><option value="Class C">Clase C</option><option value="Commercial Driver">Conductor comercial</option></select></label><p class="exam-note">Cada intento cambia el orden. Las respuestas quedan ocultas hasta terminar.</p></div>`;$$('[data-exam-size]').forEach(b=>b.onclick=()=>startCustomExam(+b.dataset.examSize))}
function startCustomExam(size){const filter=$('#examSection').value;const pool=filter==='all'?verifiedQuestionBank:verifiedQuestionBank.filter(q=>q.section.includes(filter));customExam=shuffle(pool).slice(0,Math.min(size,pool.length));customExamIndex=0;customExamAnswers={};customExamFinished=false;renderCustomExamQuestion()}
function renderCustomExamQuestion(){const q=customExam[customExamIndex],answer=customExamAnswers[customExamIndex],answered=Object.keys(customExamAnswers).length;if(!q)return renderExamBuilder();$('#customExamShell').innerHTML=`<div class="custom-exam-head"><div><small>SIMULACIÓN PERSONALIZADA</small><strong>${customExamIndex+1} / ${customExam.length}</strong></div><div class="custom-progress"><i style="width:${(customExamIndex+1)/customExam.length*100}%"></i></div><span>${answered} respondidas</span></div><div class="custom-exam-body"><article><header><strong>Página ${q.page} · Pregunta ${q.number}</strong><small>${q.section} · documento original</small></header><div><img src="assets/questionnaire/page-${String(q.page).padStart(2,'0')}.jpg" alt="Página ${q.page} del cuestionario original"></div></article><aside><p class="eyebrow dark"><span></span> TU RESPUESTA</p><h3>Localiza la pregunta ${q.number} en el original.</h3><p>Selecciona una opción. La clave permanecerá oculta hasta entregar el examen.</p><div class="custom-answer-options">${['A','B','C'].map(letter=>`<button class="${answer===letter?'selected':''}" data-custom-answer="${letter}">${letter}</button>`).join('')}</div><div class="custom-navigation"><button id="customPrev" ${customExamIndex===0?'disabled':''}>← Anterior</button><button id="customNext">${customExamIndex===customExam.length-1?'Revisar y entregar':'Siguiente →'}</button></div><button class="exam-exit" id="customExit">Salir y crear otro examen</button></aside></div>`;$$('[data-custom-answer]').forEach(b=>b.onclick=()=>{customExamAnswers[customExamIndex]=b.dataset.customAnswer;renderCustomExamQuestion()});$('#customPrev').onclick=()=>{customExamIndex--;renderCustomExamQuestion()};$('#customNext').onclick=()=>{if(customExamIndex===customExam.length-1)renderCustomExamReview();else{customExamIndex++;renderCustomExamQuestion()}};$('#customExit').onclick=renderExamBuilder}
function renderCustomExamReview(){const unanswered=customExam.length-Object.keys(customExamAnswers).length;$('#customExamShell').innerHTML=`<div class="exam-review"><p class="eyebrow dark"><span></span> REVISIÓN ANTES DE ENTREGAR</p><h2>${unanswered?`${unanswered} sin responder`:'Todo listo'}</h2><p>Puedes regresar a cualquier pregunta o entregar para revelar la clave.</p><div class="review-map">${customExam.map((q,i)=>`<button class="${customExamAnswers[i]?'answered':''}" data-review-jump="${i}">${i+1}</button>`).join('')}</div><div class="review-actions"><button id="reviewBack">← Continuar respondiendo</button><button class="grade-source" id="submitCustomExam">Entregar y calificar</button></div></div>`;$$('[data-review-jump]').forEach(b=>b.onclick=()=>{customExamIndex=+b.dataset.reviewJump;renderCustomExamQuestion()});$('#reviewBack').onclick=()=>renderCustomExamQuestion();$('#submitCustomExam').onclick=finishCustomExam}
function finishCustomExam(){customExamFinished=true;const score=customExam.filter((q,i)=>customExamAnswers[i]===q.correct).length,percent=Math.round(score/customExam.length*100);const history=JSON.parse(localStorage.getItem('rutaCdlExamHistory')||'[]');history.unshift({date:new Date().toISOString(),size:customExam.length,score,percent});localStorage.setItem('rutaCdlExamHistory',JSON.stringify(history.slice(0,20)));$('#customExamShell').innerHTML=`<div class="exam-results"><div class="result-ring"><strong>${percent}%</strong><span>${score}/${customExam.length}</span></div><div><p class="eyebrow dark"><span></span> RESULTADO FINAL</p><h2>${percent>=80?'Nivel de aprobación':'Sigue practicando'}</h2><p>${customExam.length-score} respuestas requieren revisión. Selecciona una para volver a la página fuente y comparar la clave.</p><div class="mistake-list">${customExam.map((q,i)=>({q,i})).filter(x=>customExamAnswers[x.i]!==x.q.correct).map(({q,i})=>`<button data-result-jump="${i}"><span>Pág. ${q.page} · #${q.number}</span><b>${customExamAnswers[i]||'—'} → ${q.correct}</b></button>`).join('')||'<strong>¡No hubo errores!</strong>'}</div><button class="grade-source" id="newCustomExam">Crear otro examen</button></div></div>`;$$('[data-result-jump]').forEach(b=>b.onclick=()=>{customExamIndex=+b.dataset.resultJump;renderCustomExamQuestion();const q=customExam[customExamIndex];setTimeout(()=>{const aside=$('#customExamShell aside');if(aside)aside.insertAdjacentHTML('afterbegin',`<div class="result-correction">Tu respuesta: <b>${customExamAnswers[customExamIndex]||'—'}</b> · Clave: <b>${q.correct}</b></div>`)},0)});$('#newCustomExam').onclick=renderExamBuilder;updateStats()}
function renderSourceExam(){const pageKey=`p${sourceExamPage}`,form=pageForms[sourceExamPage],answers=sourceAnswers[pageKey]||{},key=form.key||{},graded=sourceAnswers[`${pageKey}Graded`],answered=form.numbers.filter(n=>answers[n]).length,score=form.numbers.filter(n=>key[n]&&answers[n]===key[n]).length,keyCount=Object.keys(key).length;$('#sourceExamShell').innerHTML=`<div class="source-exam-head"><div><strong>${form.section} · Página ${sourceExamPage}</strong><small>${form.numbers.length} preguntas visibles · números ${form.numbers[0]}–${form.numbers.at(-1)} según el formulario original</small></div><div><button id="sourceExamPrev">←</button><span>${String(sourceExamPage).padStart(2,'0')} / 26</span><button id="sourceExamNext">→</button></div></div><div class="source-exam-body"><div class="source-exam-page"><img src="assets/questionnaire/page-${String(sourceExamPage).padStart(2,'0')}.jpg" alt="Página ${sourceExamPage} original"></div><aside class="answer-sheet"><p class="eyebrow dark"><span></span> HOJA DE RESPUESTAS REAL</p><h3>${form.section}</h3><p>Solo aparecen los números impresos en esta página. Los saltos se conservan tal como vienen en el PDF.</p><div class="answer-sheet-grid">${form.numbers.map(n=>`<div class="answer-row ${graded&&key[n]?(answers[n]===key[n]?'row-correct':'row-wrong'):''}"><span>${n}</span>${['A','B','C'].map(letter=>`<button class="${answers[n]===letter?'selected':''} ${graded&&key[n]===letter?'key-answer':''}" data-source-answer="${n}" data-source-letter="${letter}">${letter}</button>`).join('')}</div>`).join('')}</div><div class="source-answer-progress"><strong>${answered}/${form.numbers.length}</strong> respondidas · <strong>${keyCount}/${form.numbers.length}</strong> respuestas verificadas</div>${keyCount?`<button class="grade-source" id="gradeSource">${graded?'Ocultar revisión':'Revisar respuestas verificadas'}</button>`:'<div class="key-pending">Clave en verificación contra el manual. Tus respuestas se guardan, pero todavía no se califican.</div>'}${graded?`<div class="source-score"><strong>${score}/${keyCount}</strong><span>correctas entre las respuestas con clave verificada</span></div>`:''}</aside></div>`;$('#sourceExamPrev').onclick=()=>{sourceExamPage=Math.max(1,sourceExamPage-1);renderSourceExam()};$('#sourceExamNext').onclick=()=>{sourceExamPage=Math.min(26,sourceExamPage+1);renderSourceExam()};$$('[data-source-answer]').forEach(b=>b.onclick=()=>{sourceAnswers[pageKey]??={};sourceAnswers[pageKey][b.dataset.sourceAnswer]=b.dataset.sourceLetter;sourceAnswers[`${pageKey}Graded`]=false;localStorage.setItem('rutaCdlSourceAnswers',JSON.stringify(sourceAnswers));renderSourceExam()});if($('#gradeSource'))$('#gradeSource').onclick=()=>{sourceAnswers[`${pageKey}Graded`]=!graded;localStorage.setItem('rutaCdlSourceAnswers',JSON.stringify(sourceAnswers));renderSourceExam()}}
