 $('.answer-sheet').insertAdjacentHTML('afterbegin',`<div class="global-source-progress"><span>PROGRESO GLOBAL</span><strong>${totalAnswered} / 255</strong><i><em style="width:${Math.round(totalAnswered/255*100)}%"></em></i><small>Las numeraciones se repiten porque son formularios distintos; el progreso reúne las 26 páginas.</small></div>`);
 $$('[data-source-answer]').forEach(button=>button.addEventListener('click',markActivity,{once:true}));
 (pageForms[sourceExamPage].unanswerable||[]).forEach(number=>$$(`[data-source-answer="${number}"]`).forEach(button=>{button.disabled=true;button.title='El original muestra ?? y no incluye opciones'}));
