function openAnswerKey(){const rows=Object.entries(pageForms).map(([page,form])=>`<section><h2>Página ${page} · ${form.section}</h2><div class="answers">${form.numbers.map(n=>`<span><b>${n}</b>${form.unanswerable?.includes(n)?'—':form.key[n]}</span>`).join('')}</div></section>`).join('');const win=open('','_blank');win.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Clave completa · Ruta CDL</title><style>body{font:14px Arial;margin:40px;color:#102637}header{border-bottom:4px solid #f4b941;padding-bottom:20px}h1{margin:0}p{color:#60717d}section{break-inside:avoid;border-bottom:1px solid #ddd;padding:15px 0}h2{font-size:15px}.answers{display:flex;flex-wrap:wrap;gap:7px}.answers span{border:1px solid #bcc8ce;border-radius:5px;padding:7px 10px}.answers b{margin-right:8px;color:#2463a9}@media print{button{display:none}}</style></head><body><header><h1>Clave del cuestionario histórico</h1><p>Fuente: “Cuestionario impreso - Ingles.pdf”, basado en el Manual Comercial 2003. Esta clave sirve para estudiar el formulario histórico; el manual vigente tiene prioridad.</p><button onclick="print()">Imprimir / guardar PDF</button></header>${rows}<p><b>—</b> significa que el original imprime “??” y no proporciona una pregunta ni opciones.</p></body></html>`);win.document.close()}
