function renderScanRail(){
  $('#thumbnailRail').innerHTML=Array.from({length:26},(_,i)=>`<button class="scan-thumb ${i+1===scanPage?'active':''}" data-scan="${i+1}"><img loading="lazy" src="assets/questionnaire/page-${String(i+1).padStart(2,'0')}.jpg" alt="Miniatura de la página ${i+1}"><span>${String(i+1).padStart(2,'0')}</span></button>`).join('');
  $$('[data-scan]').forEach(b=>b.onclick=()=>selectScan(+b.dataset.scan));
}
function selectScan(page){scanPage=Math.max(1,Math.min(26,page));const code=String(scanPage).padStart(2,'0');$('#scanImage').src=`assets/questionnaire/page-${code}.jpg`;$('#scanImage').alt=`Página ${scanPage} del cuestionario original`;$('#scanTitle').textContent=`Página ${scanPage}`;$('#scanCount').textContent=`${code} / 26`;$('#notesPage').textContent=scanPage;$('#notesInput').value=localStorage.getItem(`rutaCdlNote${scanPage}`)||'';renderScanRail();const active=$(`[data-scan="${scanPage}"]`);if(active)active.scrollIntoView({block:'nearest'})}
function setZoom(delta){scanZoom=Math.max(35,Math.min(140,scanZoom+delta));$('#scanImage').style.width=`${scanZoom}%`;$('#zoomLabel').textContent=`${scanZoom}%`}
const compareDocuments={commercial:{en:'DL-650-2019-2021-Aug-2023-passes-accessibility.pdf',es:'Commercial-Driver-Handbook-Spanish-Official.pdf',enTitle:'Commercial Driver Handbook',esTitle:'Manual del Conductor Comercial',note:'<strong>Correspondencia completa disponible.</strong> Ambas publicaciones contienen 208 páginas y conservan la estructura del Manual del Conductor Comercial.'},general:{en:'8-11-25-DL-600-R6-2025-WWW.pdf',es:'California-Driver-Handbook-2025-Spanish-Official.pdf',enTitle:"California Driver’s Handbook",esTitle:'Resumen del Manual del Automovilista',note:'<strong>Publicación oficial no equivalente página por página.</strong> El DMV ofrece la edición española como un resumen de 68 páginas frente a las 92 páginas de la edición inglesa.'}};
function selectComparison(key){const d=compareDocuments[key];$$('[data-compare]').forEach(b=>b.classList.toggle('active',b.dataset.compare===key));$('#compareEnglish').data=encodeURI(d.en);$('#compareSpanish').data=encodeURI(d.es);$('#compareEnglishTitle').textContent=d.enTitle;$('#compareSpanishTitle').textContent=d.esTitle;$('#compareEnglishOpen').href=d.en;$('#compareSpanishOpen').href=d.es;$('#compareNote').innerHTML=d.note}
$('#scanPrev').onclick=()=>selectScan(scanPage-1);$('#scanNext').onclick=()=>selectScan(scanPage+1);$('#zoomIn').onclick=()=>setZoom(10);$('#zoomOut').onclick=()=>setZoom(-10);$('#scanFullscreen').onclick=()=>$('.scan-workspace').classList.toggle('focus-mode');$$('[data-tool]').forEach(b=>b.onclick=()=>{const tool=b.dataset.tool;if(tool==='focus')$('.scan-workspace').classList.toggle('focus-mode');if(tool==='notes')$('#pageNotes').hidden=!$('#pageNotes').hidden;if(tool==='practice'){$('#practica').scrollIntoView({behavior:'smooth'});showPractice('quiz')}});$('#notesInput').oninput=e=>localStorage.setItem(`rutaCdlNote${scanPage}`,e.target.value);$$('[data-compare]').forEach(b=>b.onclick=()=>selectComparison(b.dataset.compare));selectComparison('commercial');
let translationPage=1,translationFont=15,translationText='';
$('#translationPageSelect').innerHTML=Array.from({length:26},(_,i)=>`<option value="${i+1}">Página ${i+1}</option>`).join('');
function escapeHtml(value){return value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function paintTranslation(){const query=$('#translationSearch').value.trim();let safe=escapeHtml(translationText);if(query){const escaped=query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');safe=safe.replace(new RegExp(escaped,'gi'),m=>`<mark>${m}</mark>`)}$('#translatedPage').innerHTML=safe||'<p>No fue posible cargar esta página.</p>';$('#translatedPage').style.fontSize=`${translationFont}px`;const first=$('#translatedPage mark');if(first)first.scrollIntoView({block:'center'})}
function selectTranslationPage(page){translationPage=Math.max(1,Math.min(26,+page));const code=String(translationPage).padStart(2,'0');$('#translationPageCount').textContent=`${code} / 26`;$('#translationSourcePage').textContent=translationPage;$('#translationPageSelect').value=translationPage;$('#translationSourceImage').src=`assets/questionnaire/page-${code}.jpg`;$('#translationSourceImage').alt=`Página ${translationPage} del cuestionario original en inglés`;translationText=(window.QUESTIONNAIRE_SPANISH||{})[code]||'Traducción no disponible.';paintTranslation()}
$('#translationPrev').onclick=()=>selectTranslationPage(translationPage-1);$('#translationNext').onclick=()=>selectTranslationPage(translationPage+1);$('#translationPageSelect').onchange=e=>selectTranslationPage(e.target.value);$('#translationSearch').oninput=paintTranslation;$('#translationSmaller').onclick=()=>{translationFont=Math.max(11,translationFont-1);paintTranslation()};$('#translationLarger').onclick=()=>{translationFont=Math.min(24,translationFont+1);paintTranslation()};selectTranslationPage(1);
$('#languageButton').addEventListener('click',e=>{e.stopImmediatePropagation();const d=documents[currentDocument];if(!d.spanishFile){$('#traduccion').scrollIntoView({behavior:'smooth'});return}currentDocLanguage=currentDocLanguage==='en'?'es':'en';selectDocument(currentDocument)},true);
$('#clearProgress').addEventListener('click',e=>{e.stopImmediatePropagation();if(confirm('¿Borrar respuestas, notas, tarjetas y todo el progreso guardado en este navegador?')){Object.keys(localStorage).filter(k=>k.startsWith('rutaCdl')).forEach(k=>localStorage.removeItem(k));location.reload()}},true);
